# Generated by manage.py generate_test_cases.
from unittest.mock import patch

from django.contrib.contenttypes.models import ContentType

from bloomerp.filters.definition import Filter, FilterCondition
from bloomerp.models.project_management.todo import Todo
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestUpdateObjectComponent(BloomerpComponentTestCase):
    """Tests function `update_object` from `bloomerp/components/objects/crud/create_update.py`."""

    view_name = 'components_update_object'
    auto_create_customers = False

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Keep excluded records outside administrator edit-form requests."""
        return [
            RequestScenario(
                name="Administrator cannot open a base-filtered record for editing",
                user=self.admin_user,
                prepare=self.prepare_excluded_todo,
                cleanup=self.restore_model_config,
                expected=ExpectedResult(status_code=404),
            )
        ]

    def prepare_excluded_todo(self, scenario: RequestScenario) -> None:
        """Create a record excluded by the model's application base filter."""
        todo = Todo.objects.create(title="Hidden record")
        scenario.view_kwargs = {
            "content_type_id": ContentType.objects.get_for_model(Todo).pk,
            "object_id": str(todo.pk),
        }
        config = Todo.bloomerp_config.model_copy(
            update={
                "base_filter": Filter(
                    connector="AND",
                    conditions=[
                        FilterCondition(
                            field_path="title", lookup_id="equals", value="Visible record"
                        )
                    ],
                )
            }
        )
        self.base_filter_patch = patch.object(Todo, "bloomerp_config", config)
        self.base_filter_patch.start()

    def restore_model_config(self, _scenario: RequestScenario) -> None:
        """Restore the shared model configuration after the request."""
        self.base_filter_patch.stop()
